   475  static struct expr *
   476  make_cmp__(const struct expr_field *f, enum expr_relop r,
   477               const union expr_constant *c)
   478  {
   479      struct expr *e = xzalloc(sizeof *e);
   480      e->type = EXPR_T_CMP;
   481      e->cmp.symbol = f->symbol;
   482      e->cmp.relop = r;
   483      if (f->symbol->width) {
   484          bitwise_copy(&c->value, sizeof c->value, 0,
   485                       &e->cmp.value, sizeof e->cmp.value, f->ofs,
   486                       f->n_bits);
   487          if (c->masked) {
   488              bitwise_copy(&c->mask, sizeof c->mask, 0,
   489                           &e->cmp.mask, sizeof e->cmp.mask, f->ofs,
   490                           f->n_bits);
   491          } else {
   492              bitwise_one(&e->cmp.mask, sizeof e->cmp.mask, f->ofs,
   493                          f->n_bits);
   494          }
   495      } else {
   496          e->cmp.string = xstrdup(c->string);
   497      }
   498      return e;
   499  }
