   501  /* Returns the minimum reasonable width for integer constant 'c'. */
   502  static int
   503  expr_constant_width(const union expr_constant *c)
   504  {
   505      if (c->masked) {
   506          return mf_subvalue_width(&c->mask);
   507      }
   508
   509      switch (c->format) {
   510      case LEX_F_DECIMAL:
   511      case LEX_F_HEXADECIMAL:
   512          return mf_subvalue_width(&c->value);
   513
   514      case LEX_F_IPV4:
   515          return 32;
   516
   517      case LEX_F_IPV6:
   518          return 128;
   519
   520      case LEX_F_ETHERNET:
   521          return 48;
   522
   523      default:
   524          OVS_NOT_REACHED();
   525      }
   526  }
