   528  static bool
   529  type_check(struct expr_context *ctx, const struct expr_field *f,
   530             struct expr_constant_set *cs)
   531  {
   532      if (cs->type != (f->symbol->width ? EXPR_C_INTEGER : EXPR_C_STRING)) {
   533          lexer_error(ctx->lexer,
   534                      "%s field %s is not compatible with %s constant.",
   535                      f->symbol->width ? "Integer" : "String",
   536                      f->symbol->name,
   537                      cs->type == EXPR_C_INTEGER ? "integer" : "string");
   538          return false;
   539      }
   540
   541      if (f->symbol->width) {
   542          for (size_t i = 0; i < cs->n_values; i++) {
   543              int w = expr_constant_width(&cs->values[i]);
   544              if (w > f->symbol->width) {
   545                  lexer_error(ctx->lexer,
   546                              "%d-bit constant is not compatible with %d-bit "
   547                              "field %s.", w, f->symbol->width, f->symbol->name);
   548                  return false;
   549              }
   550          }
   551      }
   552
   553      return true;
   554  }
   555
   556  static struct expr *
   557  make_cmp(struct expr_context *ctx,
   558           const struct expr_field *f, enum expr_relop r,
   559           struct expr_constant_set *cs)
   560  {
   561      struct expr *e = NULL;
   562
   563      if (!type_check(ctx, f, cs)) {
   564          goto exit;
   565      }
   566
   567      if (r != EXPR_R_EQ && r != EXPR_R_NE) {
   568          if (cs->in_curlies) {
   569              lexer_error(ctx->lexer, "Only == and != operators may be used "
   570                          "with value sets.");
   571              goto exit;
   572          }
   573          if (f->symbol->level == EXPR_L_NOMINAL ||
   574              f->symbol->level == EXPR_L_BOOLEAN) {
   575              lexer_error(ctx->lexer, "Only == and != operators may be used "
   576                          "with %s field %s.",
   577                          expr_level_to_string(f->symbol->level),
   578                          f->symbol->name);
   579              goto exit;
   580          }
   581          if (cs->values[0].masked) {
   582              lexer_error(ctx->lexer, "Only == and != operators may be used "
   583                          "with masked constants.  Consider using subfields "
   584                          "instead (e.g. eth.src[0..15] > 0x1111 in place of "
   585                          "eth.src > 00:00:00:00:11:11/00:00:00:00:ff:ff).");
   586              goto exit;
   587          }
   588      }
   589
   590      if (f->symbol->level == EXPR_L_NOMINAL) {
   591          if (f->symbol->predicate) {
   592              ovs_assert(f->symbol->width > 0);
   593              for (size_t i = 0; i < cs->n_values; i++) {
   594                  const union mf_subvalue *value = &cs->values[i].value;
   595                  bool positive = (value->integer & htonll(1)) != 0;
   596                  positive ^= r == EXPR_R_NE;
   597                  positive ^= ctx->not;
   598                  if (!positive) {
   599                      const char *name = f->symbol->name;
   600                      lexer_error(ctx->lexer,
   601                                  "Nominal predicate %s may only be tested "
   602                                  "positively, e.g. `%s' or `%s == 1' but not "
   603                                  "`!%s' or `%s == 0'.",
   604                                  name, name, name, name, name);
   605                      goto exit;
   606                  }
   607              }
   608          } else if (r != (ctx->not ? EXPR_R_NE : EXPR_R_EQ)) {
   609              lexer_error(ctx->lexer, "Nominal field %s may only be tested for "
   610                          "equality (taking enclosing `!' operators into "
   611                          "account).", f->symbol->name);
   612              goto exit;
   613          }
   614      }
   615
   616      if (!cs->n_values) {
   617          e = expr_create_boolean(r == EXPR_R_NE);
   618          goto exit;
   619      }
   620      e = make_cmp__(f, r, &cs->values[0]);
   621      for (size_t i = 1; i < cs->n_values; i++) {
   622          e = expr_combine(r == EXPR_R_EQ ? EXPR_T_OR : EXPR_T_AND,
   623                           e, make_cmp__(f, r, &cs->values[i]));
   624      }
   625  exit:
   626      expr_constant_set_destroy(cs);
   627      return e;
   628  }
