   630  static bool
   631  parse_field(struct expr_context *ctx, struct expr_field *f)
   632  {
   633      const struct expr_symbol *symbol;
   634
   635      if (ctx->lexer->token.type != LEX_T_ID) {
   636          lexer_syntax_error(ctx->lexer, "expecting field name");
   637          return false;
   638      }
   639
   640      symbol = shash_find_data(ctx->symtab, ctx->lexer->token.s);
   641      if (!symbol) {
   642          lexer_syntax_error(ctx->lexer, "expecting field name");
   643          return false;
   644      }
   645      lexer_get(ctx->lexer);
   646
   647      f->symbol = symbol;
   648      if (lexer_match(ctx->lexer, LEX_T_LSQUARE)) {
   649          int low, high;
   650
   651          if (!symbol->width) {
   652              lexer_error(ctx->lexer,
   653                          "Cannot select subfield of string field %s.",
   654                          symbol->name);
   655              return false;
   656          }
   657
   658          if (!lexer_force_int(ctx->lexer, &low)) {
   659              return false;
   660          }
  1040  {
  1041      struct shash_node *node, *next;
  1042
  1043      SHASH_FOR_EACH_SAFE (node, next, const_sets) {
  1044          struct expr_constant_set *cs = node->data;
  1045
  1046          shash_delete(const_sets, node);
  1047          expr_constant_set_destroy(cs);
  1048          free(cs);
  1049      }
  1050  }
