  1052  static struct expr *
  1053  parse_chassis_resident(struct expr_context *ctx)
  1054  {
  1055      if (ctx->lexer->token.type != LEX_T_STRING) {
  1056          lexer_syntax_error(ctx->lexer, "expecting string");
  1057          return NULL;
  1058      }
  1059
  1060      struct expr *e = xzalloc(sizeof *e);
  1061      e->type = EXPR_T_CONDITION;
  1062      e->cond.type = EXPR_COND_CHASSIS_RESIDENT;
  1063      e->cond.not = false;
  1064      e->cond.string = xstrdup(ctx->lexer->token.s);
  1065
  1066      lexer_get(ctx->lexer);
  1067      if (!lexer_force_match(ctx->lexer, LEX_T_RPAREN)) {
  1068          expr_destroy(e);
  1069          return NULL;
  1070      }
  1071
  1072      return e;
  1073  }
  1074
  1075  static struct expr *
  1076  expr_parse_primary(struct expr_context *ctx, bool *atomic)
  1077  {
  1078      *atomic = false;
  1079      if (lexer_match(ctx->lexer, LEX_T_LPAREN)) {
  1080          struct expr *e = expr_parse__(ctx);
  1081          if (!lexer_force_match(ctx->lexer, LEX_T_RPAREN)) {
  1082              expr_destroy(e);
  1083              return NULL;
  1084          }
  1085          *atomic = true;
  1086          return e;
  1087      }
  1088
  1089      if (ctx->lexer->token.type == LEX_T_ID) {
  1090          struct expr_field f;
  1091          enum expr_relop r;
  1092          struct expr_constant_set c;
  1093
  1094          if (lexer_lookahead(ctx->lexer) == LEX_T_LPAREN) {
  1095              if (lexer_match_id(ctx->lexer, "is_chassis_resident")) {
  1096                  lexer_get(ctx->lexer); /* Skip "(". */
  1097                  *atomic = true;
  1098                  return parse_chassis_resident(ctx);
  1099              }
  1100              lexer_error(ctx->lexer, "parsing function name");
  1101              return NULL;
  1102          }
  1103
  1104          if (!parse_field(ctx, &f)) {
  1105              return NULL;
  1106          }
  1107
  1108          if (!expr_relop_from_token(ctx->lexer->token.type, &r)) {
  1109              if (!f.n_bits || ctx->lexer->token.type == LEX_T_EQUALS) {
  1110                  lexer_syntax_error(ctx->lexer,
  1111                                     "expecting relational operator");
  1112                  return NULL;
  1113              } else if (f.n_bits > 1 && !ctx->not) {
  1114                  lexer_error(ctx->lexer,
  1115                              "Explicit `!= 0' is required for inequality "
  1116                              "test of multibit field against 0.");
  1117                  return NULL;
  1118              }
  1119
  1120              *atomic = true;
  1121
  1122              union expr_constant *cst = xzalloc(sizeof *cst);
  1123              cst->format = LEX_F_HEXADECIMAL;
  1124              cst->masked = false;
  1125
  1126              c.type = EXPR_C_INTEGER;
  1127              c.values = cst;
  1128              c.n_values = 1;
  1129              c.in_curlies = false;
  1130              return make_cmp(ctx, &f, EXPR_R_NE, &c);
  1131          } else if (parse_relop(ctx, &r) && parse_constant_set(ctx, &c)) {
  1132              return make_cmp(ctx, &f, r, &c);
  1133          } else {
  1134              return NULL;
  1135          }
  1136      } else {
  1137          struct expr_constant_set c1;
  1138          if (!parse_constant_set(ctx, &c1)) {
  1139              return NULL;
  1140          }
  1141
  1142          if (!expr_relop_from_token(ctx->lexer->token.type, NULL)
  1143              && c1.n_values == 1
  1144              && c1.type == EXPR_C_INTEGER
  1145              && c1.values[0].format == LEX_F_DECIMAL
  1146              && !c1.values[0].masked
  1147              && !c1.in_curlies) {
  1148              uint64_t x = ntohll(c1.values[0].value.integer);
  1149              if (x <= 1) {
  1150                  *atomic = true;
  1151                  expr_constant_set_destroy(&c1);
  1152                  return expr_create_boolean(x);
  1153              }
  1154          }
  1155
  1156          enum expr_relop r1;
  1157          struct expr_field f;
  1158          if (!parse_relop(ctx, &r1) || !parse_field(ctx, &f)) {
  1159              expr_constant_set_destroy(&c1);
  1160              return NULL;
  1161          }
  1162
  1163          if (!expr_relop_from_token(ctx->lexer->token.type, NULL)) {
  1164              return make_cmp(ctx, &f, expr_relop_turn(r1), &c1);
  1165          }
  1166
  1167          enum expr_relop r2;
  1168          struct expr_constant_set c2;
  1169          if (!parse_relop(ctx, &r2) || !parse_constant_set(ctx, &c2)) {
  1170              expr_constant_set_destroy(&c1);
  1171              return NULL;
  1172          } else {
  1173              /* Reject "1 == field == 2", "1 < field > 2", and so on. */
  1174              if (!(((r1 == EXPR_R_LT || r1 == EXPR_R_LE) &&
  1175                     (r2 == EXPR_R_LT || r2 == EXPR_R_LE)) ||
  1176                    ((r1 == EXPR_R_GT || r1 == EXPR_R_GE) &&
  1177                     (r2 == EXPR_R_GT || r2 == EXPR_R_GE)))) {
  1178                  lexer_error(ctx->lexer, "Range expressions must have the "
  1179                              "form `x < field < y' or `x > field > y', with "
  1180                              "each `<' optionally replaced by `<=' or `>' by "
  1181                              "`>=').");
  1182                  expr_constant_set_destroy(&c1);
  1183                  expr_constant_set_destroy(&c2);
  1184                  return NULL;
  1185              }
  1186
  1187              struct expr *e1 = make_cmp(ctx, &f, expr_relop_turn(r1), &c1);
  1188              struct expr *e2 = make_cmp(ctx, &f, r2, &c2);
  1189              if (ctx->lexer->error) {
  1190                  expr_destroy(e1);
  1191                  expr_destroy(e2);
  1192                  return NULL;
  1193              }
  1194              return expr_combine(EXPR_T_AND, e1, e2);
  1195          }
  1196      }
  1197  }
