  1199  static struct expr *
  1200  expr_parse_not(struct expr_context *ctx)
  1201  {
  1202      bool atomic;
  1203
  1204      if (lexer_match(ctx->lexer, LEX_T_LOG_NOT)) {
  1205          ctx->not = !ctx->not;
  1206          struct expr *expr = expr_parse_primary(ctx, &atomic);
  1207          ctx->not = !ctx->not;
  1208
  1209          if (expr) {
  1210              if (!atomic) {
  1211                  lexer_error(ctx->lexer,
  1212                              "Missing parentheses around operand of !.");
  1213                  expr_destroy(expr);
  1214                  return NULL;
  1215              }
  1216              expr_not(expr);
  1217          }
  1218          return expr;
  1219      } else {
  1220          return expr_parse_primary(ctx, &atomic);
  1221      }
  1222  }
